export type Product = {
  id: string
  name: string
  category: string
  description: string
  price: number
  image: string
  inStock: boolean
}

export function formatINR(value: number): string {
  return `₹${value.toLocaleString("en-IN", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  })}`
}

export function applyMargin(basePrice: number): number {
  let margin = 0
  if (basePrice >= 3000) margin = 150
  else if (basePrice >= 999) margin = 70
  else if (basePrice >= 400) margin = 50
  else if (basePrice >= 230) margin = 35
  else if (basePrice >= 150) margin = 20
  else if (basePrice >= 70) margin = 15
  else if (basePrice >= 30) margin = 7
  else if (basePrice >= 10) margin = 3
  else margin = 1
  return basePrice + margin
}

export function slugify(name: string): string {
  return name
    .replace(/&#215;/g, "x")
    .replace(/&amp;/g, "&")
    .replace(/&mdash;/g, "-")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
}

