export const products: Product[] = raw.map((p) => ({
  id: slugify(p.name),
  name: p.name,
  category: p.category,
  description: p.description,
  price: applyMargin(p.price!),
  image: p.image,
  inStock: p.inStock !== false,
}))

export const categories: string[] = Array.from(new Set(products.map((p) => p.category))).sort()
